async function timeoutFetch(timeout, url, onerror = () => console.error('Request aborted due to timeout')) {
    const option = {};
    const ctrl = new AbortController();
    option.signal = ctrl.signal;

    const tid = setTimeout(() => {
        onerror();
        ctrl.abort();
    }, timeout);

    try {
        return await fetch(url, option);
    } finally {
        clearTimeout(tid);
    }   
}

/**
 * 
 * @param {number} interval 
 * @param {() => void} timeout 
 * @param {() => void} callee 
 * @returns {() => void} Canceller of the task.
 */
function intervalTask(interval, timeout, callee) {
    let isRunning = false;
    const timerId = setInterval(() => {
        if (isRunning) {
            timeout();
        } else {
            try {
                isRunning = true;
                callee();
            } finally {
                isRunning = false;
            }
        }
    }, interval);
    return () => void(clearInterval(timerId));
}

